/**
 * The tray icon, embedded so the built app needs no file next to it. The PNGs are generated by tools/make_icons.ts from
 * outputs/agent-studio/icons/src/icon-small.svg (the small drawing of the app icon) into tray_icon_data.ts.
 *
 * Every platform and theme gets the full-colour app icon (the teal tile with the hat and the two squares): it reads on light and
 * dark taskbars and panels alike, so nothing follows the theme. Windows: 16 px when the system's small icon is 16 px (100% scaling),
 * else 32 px, which Windows scales down to 20/24 px. macOS and Linux: 32 px (the panel scales it).
 */
import { user32 } from '../platform/win32.ts';
import { TRAY_PNG_BASE64 } from './tray_icon_data.ts';

export type TraySize = 16 | 32;

/** Which tray image size to use. smallIconPx: the system's small icon size (GetSystemMetrics SM_CXSMICON, 0 when unknown). */
export function chooseTraySize(os: typeof Deno.build.os, smallIconPx: number): TraySize {
  return os === 'windows' && smallIconPx > 0 && smallIconPx <= 16 ? 16 : 32;
}

/** The colour PNG at a size. */
export function trayIconBytes(size: TraySize): Uint8Array {
  const b64 = TRAY_PNG_BASE64[`color-${size}`] ?? TRAY_PNG_BASE64['color-32'];
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

/** Windows: the small icon width in pixels (SM_CXSMICON), as the tray will draw it; 0 when unknown. */
export function windowsSmallIconPx(): number {
  if (Deno.build.os !== 'windows') return 0;
  try {
    return user32().GetSystemMetrics(49); // SM_CXSMICON
  } catch {
    return 0;
  }
}

/** The tray PNG for this machine, read now (the scaling at start-up). */
export function trayIconPng(): Uint8Array {
  return trayIconBytes(chooseTraySize(Deno.build.os, windowsSmallIconPx()));
}
